arguments.command:
cd /src/mupdf && python - <<'PY'
from pathlib import Path
path = Path('source/pdf/pdf-op-run.c')
data = path.read_text(encoding='utf-8')
old = "static void nest_layer_clip(fz_context *ctx, pdf_run_processor *proc)
{
	proc->nest_mark[proc->nest_depth++] = CLIP_MARK;
}
"
new = "static void nest_layer_clip(fz_context *ctx, pdf_run_processor *proc)
{
	/* nest_mark is a fixed-size stack. A crafted PDF can drive nesting beyond
	 * its capacity via repeated clipping/marked-content transitions, which would
	 * otherwise result in a 4-byte write just past the end of the heap allocated
	 * pdf_run_processor.
	 */
	if (proc->nest_depth == nelem(proc->nest_mark))
		fz_throw(ctx, FZ_ERROR_LIMIT, "layer/clip nesting too deep");

	proc->nest_mark[proc->nest_depth++] = CLIP_MARK;
}
"
if old not in data:
    raise SystemExit('Target snippet not found; aborting')
path.write_text(data.replace(old, new), encoding='utf-8')
print('patched')
PY
rg -n "static void nest_layer_clip|layer/clip nesting too deep" -n source/pdf/pdf-op-run.c | head

